const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const closeX=()=>{const h=[...document.querySelectorAll('*')].find(e=>e.childElementCount===0&&e.innerText?.trim()==='Manage Columns'); if(!h) return; let p=h.parentElement; while(p && !p.querySelector('button')) p=p.parentElement; p.querySelector('button').click();};
closeX(); await sleep(500);
const inp=[...document.querySelectorAll('input')].find(i=>/Player Traits|Advanced Stats/.test(i.value));
const out={};
const groups=['QB','RB','WR','TE','OT','IOL','IDL','EDGE','OB-LB','CB','SAF'];
for(const g of groups){
  inp.click(); await sleep(400);
  const opt=[...document.querySelectorAll('[role=option]')].find(o=>o.innerText.trim().startsWith(g+' '));
  if(!opt){out[g]='no option';document.body.click();continue;}
  opt.click(); await sleep(2500);
  const btn=[...document.querySelectorAll('button')].find(b=>b.innerText.trim()==='Columns'); btn.click(); await sleep(800);
  const h=[...document.querySelectorAll('*')].find(e=>e.childElementCount===0&&e.innerText?.trim()==='Manage Columns'); let p=h; while(p && !/Scrollable/.test(p.innerText)) p=p.parentElement;
  out[g]=p.innerText.split('Scrollable')[1].trim().split(/\s*\n\s*/).join(', ');
  closeX(); await sleep(500);
}
JSON.stringify({tab:inp.value,out},null,1)

