window.__run = async (groups)=>{
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const mc=()=>[...document.querySelectorAll('*')].find(e=>e.childElementCount===0&&e.innerText?.trim()==='Manage Columns');
const closeX=()=>{const h=mc(); if(!h) return; let p=h.parentElement; while(p && !p.querySelector('button')) p=p.parentElement; p.querySelector('button').click();};
window.__out=window.__out||{}; window.__done=false;
closeX(); await sleep(500);
const inp=[...document.querySelectorAll('input')].find(i=>/Player Traits|Advanced Stats/.test(i.value));
const tab=inp.value.includes('Advanced')?'adv':'traits';
for(const g of groups){
  inp.click(); await sleep(500);
  const opt=[...document.querySelectorAll('[role=option]')].find(o=>o.innerText.trim().startsWith(g+' '));
  if(!opt){window.__out[tab+':'+g]='no option';continue;}
  opt.click(); await sleep(2500);
  [...document.querySelectorAll('button')].find(b=>b.innerText.trim()==='Columns').click(); await sleep(800);
  let p=mc(); while(p && !/Scrollable/.test(p.innerText)) p=p.parentElement;
  window.__out[tab+':'+g]=p?p.innerText.split('Scrollable')[1].trim().split(/\s*\n\s*/).join(', '):'no panel';
  closeX(); await sleep(500);
}
window.__done=true;};
window.__run(['QB','RB','WR','TE','OT','IOL','IDL','EDGE','OB-LB','CB','SAF']); 'started'

