document.body.click();
const srcs=[...document.scripts].map(s=>s.src).filter(Boolean).concat(performance.getEntriesByType('resource').map(r=>r.name).filter(n=>/\.js(\?|$)/.test(n)));
const uniq=[...new Set(srcs)]; const hits=[];
for(const u of uniq){try{const t=await (await fetch(u)).text(); for(const kw of ['Pull Agility','Perimeter Speed','Reaction Time','Targeted Coverage','Closing']){let i=t.indexOf(kw); let n=0; while(i>=0&&n<3){hits.push(kw+' @'+u.split('/').pop()+': '+t.slice(Math.max(0,i-100),i+500).replace(/\s+/g,' ')); i=t.indexOf(kw,i+1); n++;}}}catch(e){}}
uniq.length+' scripts\n'+hits.join('\n---\n').slice(0,6000)

